package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s string
	fmt.Fscan(in, &n, &s)

	removed, consecutiveX := 0, 0
	for _, ch := range s {
		if ch == 'x' {
			consecutiveX++
			if consecutiveX >= 3 {
				removed++
			}
		} else {
			consecutiveX = 0
		}
	}

	fmt.Println(removed)
}

